import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written double of the pricing downstream (priceOf(sku) -> euros).
const prices = { A: 10, B: 25.5, BIG: 150, EDGE: 100, HALF: 100.5, FRAC: 0.99 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const create = async (items) => (await post({ items })).json()

test('POST /orders creates an order: 201, json, sequential string id, items echoed', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }])
  assert.equal(order.total, 45)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
  const next = await create([{ sku: 'A', qty: 1 }])
  assert.equal(Number(next.id), Number(order.id) + 1)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  assert.equal((await create([{ sku: 'EDGE', qty: 1 }])).total, 100)
})

test('POST /orders: total above 100 gets 10% off', async () => {
  assert.equal((await create([{ sku: 'BIG', qty: 1 }])).total, 135)
})

test('POST /orders: total is floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 100.5 -> 90.45 -> 90; 0.99 -> 0 (floor truncates cents, total is whole euros)
  assert.equal((await create([{ sku: 'HALF', qty: 1 }])).total, 90)
  assert.equal((await create([{ sku: 'FRAC', qty: 1 }])).total, 0)
})

test('POST /orders: unknown sku (pricing returns undefined) yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null, order still created with 201
  const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders: missing qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation, price * undefined = NaN -> null
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined, ''],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 on ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('GET /orders/{id} returns a created order', async () => {
  const created = await create([{ sku: 'A', qty: 3 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/{id} unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order returns 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('GET /orders/{id} ignores a query string', async () => {
  const created = await create([{ sku: 'A', qty: 1 }])
  assert.deepEqual(await (await fetch(`${base}/orders/${created.id}?x=1`)).json(), created)
})

for (const [method, path] of [
  ['GET', '/orders'],
  ['GET', '/'],
  ['GET', '/orders/1/items'],
  ['GET', '/orders/'],
  ['POST', '/orders/1'],
  ['PUT', '/orders'],
  ['DELETE', '/orders/1'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
}
